#include "../common.h"
int main(void){char key[100],c[500];printf("Keyword for the supplied Playfair message: ");scanf("%99s",key);printf("Ciphertext (letters only): ");scanf("%499s",c);upper_letters(key);char sq[25];int used[26]={0},n=0;used[9]=1;for(int pass=0;pass<2;pass++){char *p=pass?"ABCDEFGHIJKLMNOPQRSTUVWXYZ":key;for(;*p;p++)if(isalpha(*p)){char x=*p=='J'?'I':*p;if(!used[x-'A'])used[x-'A']=1,sq[n++]=x;}}for(int i=0;c[i]&&c[i+1];i+=2){int x=c[i]=='J'?'I':c[i],y=c[i+1]=='J'?'I':c[i+1],a=0,b=0,d=0,e=0;for(int j=0;j<25;j++){if(sq[j]==x)a=j/5,b=j%5;if(sq[j]==y)d=j/5,e=j%5;}if(a==d)x=sq[a*5+modn(b-1,5)],y=sq[d*5+modn(e-1,5)];else if(b==e)x=sq[modn(a-1,5)*5+b],y=sq[modn(d-1,5)*5+e];else x=sq[a*5+e],y=sq[d*5+b];printf("%c%c",x,y);}puts("");puts("Remove filler X characters where appropriate.");}
